import xml.etree.ElementTree as ET

def xml_to_dict(xml_string):
    """
    Converts an XML string to a nested dictionary.
    """
    root = ET.fromstring(xml_string)
    return element_to_dict(root)

def element_to_dict(element):
    """
    Recursively converts an XML element to a dictionary.
    """
    d = {}

    # Handle attributes
    for key, value in element.attrib.items():
        d['@' + key] = value

    # Handle children
    children = list(element)
    if children:
        child_data = {}
        for child in children:
            child_tag = child.tag
            child_dict = element_to_dict(child)
            if child_tag in child_data:
                if type(child_data[child_tag]) is list:
                    child_data[child_tag].append(child_dict)
                else:
                    child_data[child_tag] = [child_data[child_tag], child_dict]
            else:
                child_data[child_tag] = child_dict
        d.update(child_data)

    # Handle text content
    if element.text and element.text.strip():
        d['#text'] = element.text.strip()

    return d

if __name__ == "__main__":
    xml_string = input()
    result_dict = xml_to_dict(xml_string)
