def factorial(n):
    """
    Calculates the factorial of a non-negative integer between 1 and 50.

    Args:
        n: The integer for which to calculate the factorial.

    Returns:
        The factorial of n if n is a valid integer within the range [1, 50].
        An error message if n is not an integer or is outside the range [1, 50].
    """
    if not isinstance(n, int):
        return "Error: Input must be an integer."
    if n < 1 or n > 50:
        return "Error: Input must be between 1 and 50."
    if n == 1:
        return 1
    else:
        return n * factorial(n-1)
