def selection_sort(arr, reverse=False):
    n = len(arr)
    for i in range(n):
        min_val = i
        for j in range(i+1, n):
            if reverse:
                if arr[min_val] < arr[j]:
                    min_val = j
            else:
                if arr[min_val] > arr[j]:
                    min_val = j
        arr[i], arr[min_val] = arr[min_val], arr[i]
