def is_valid_ip(ip: str) -> bool:
    """
    Validates if a given IP address is in the correct format and if each octet 
    of the IP address is within the valid range (0-255).
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        try:
            num = int(part)
            if num < 0 or num > 255:
                return False
        except ValueError:
            return False
    return True
