function translateVowels(str, forward) {
  let result = "";
  const vowels = "aeiouAEIOU";

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (vowels.includes(char)) {
      let index = vowels.indexOf(char);
      if (forward) {
        index = (index + 1) % vowels.length;
      } else {
        index = (index - 1 + vowels.length) % vowels.length;
      }
      result += vowels[index];
    } else {
      result += char;
    }
  }

